function sound(kind='tap'){
 if(!settings.sound||document.hidden)return;
 try{
  audio=music.context();if(!audio)return;if(audio.state==='suspended')audio.resume().catch(()=>{});
  const now=audio.currentTime,notes=kind==='win'?[392,494,587]:kind==='wrong'?[160,130]:kind==='hit'?[110,75]:[330,440];
  notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type=kind==='hit'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(0,now+i*.07);g.gain.linearRampToValueAtTime(.035*settings.sfxVolume,now+i*.07+.012);g.gain.exponentialRampToValueAtTime(.0001,now+i*.07+.18);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect();};o.start(now+i*.07);o.stop(now+i*.07+.2);});
 }catch(_){}
}
