function icon(name,cls=''){if(V.icons?.[name])return '<img class="icon '+cls+'" src="assets/'+V.icons[name]+'" width="40" height="40" alt="" aria-hidden="true">';return '<svg class="icon '+cls+'" viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.orb)+'"/></svg>';}
