 const seals=e.boss?'<div class="seals" aria-label="'+b.seals+' of 2 seals opened">'+[0,1].map(i=>'<span class="seal '+(b.seals>i?'open':'')+'">'+icon(b.seals>i?'check':'orb')+'</span>').join('')+'<small>'+b.seals+'/2 seals open</small></div>':'';
